/** Loads the project's SDK and renders the managed client using its formatter. @module */
import { OptionalDependencyUnavailableError } from '@setu-ts/common';
import type { TargetRuntime } from '../constants.ts';
import type { GeneratedFile } from '../utils/file-writer.ts';
import { importFromProject } from '../utils/ts-loader.ts';
import { formatForTarget, loadPrettier, type PrettierApi } from '../utils/prettier-format.ts';

/** The exact first line identifying a file the command owns. */
export const CLIENT_MARKER =
  '// Generated by `setu client`. Do not edit; run `setu client` to regenerate.';

/** Resolves a bare package from the target project. */
export type ClientPackageLoader = (
  specifier: string,
  root: string,
) => Promise<Record<string, unknown>>;

/** Generation options passed through to the installed SDK without widening its surface. */
export interface IClientGenerationOptions {
  readonly factoryName?: string;
  readonly apiTypeName?: string;
}

/** Only direct package resolution failures mean it is absent; transitive failures propagate. */
function isMissingModule(cause: unknown, specifier: string): boolean {
  return (
    typeof cause === 'object' &&
    cause !== null &&
    'code' in cause &&
    cause.code === 'ERR_MODULE_NOT_FOUND' &&
    'message' in cause &&
    typeof cause.message === 'string' &&
    cause.message.startsWith(`Cannot find package '${specifier}' imported from `)
  );
}

/** Uses the project's formatter; the CLI copy is a fallback only when it is absent. */
async function projectPrettier(root: string, load: ClientPackageLoader): Promise<PrettierApi> {
  let module: Record<string, unknown>;
  try {
    module = await load('prettier', root);
  } catch (cause) {
    if (!isMissingModule(cause, 'prettier')) throw cause;
    return loadPrettier();
  }
  if (
    typeof module['format'] !== 'function' ||
    typeof module['resolveConfig'] !== 'function' ||
    typeof module['resolveConfigFile'] !== 'function'
  )
    throw new Error('The installed prettier has no formatting API; update it.');
  return module as unknown as PrettierApi;
}

/**
 * Generates the complete managed file with the project's installed SDK and Prettier.
 * @param document - The booted or parsed OpenAPI document
 * @param options - Names forwarded to the SDK generator
 * @param runtime - Target runtime determining header and formatting
 * @param root - Project root used for package and configuration resolution
 * @param path - Absolute output path
 * @param report - Formatting diagnostics
 * @param load - Project package loader seam
 * @returns The formatted, managed file
 */
export async function generateClientFile(
  document: Readonly<Record<string, unknown>>,
  options: IClientGenerationOptions,
  runtime: TargetRuntime,
  root: string,
  path: string,
  report: (line: string) => void,
  load: ClientPackageLoader = importFromProject,
): Promise<GeneratedFile> {
  let sdk: Record<string, unknown>;
  try {
    sdk = await load('@setu-ts/sdk', root);
  } catch (cause) {
    if (!isMissingModule(cause, '@setu-ts/sdk')) throw cause;
    const error = new OptionalDependencyUnavailableError('@setu-ts/sdk', {
      requiredBy: 'setu client',
      cause,
    });
    error.message += ' Run `setu add sdk`.';
    throw error;
  }
  const generate = sdk['generateOpenApiClient'];
  if (typeof generate !== 'function')
    throw new Error('The installed @setu-ts/sdk has no generateOpenApiClient; update it.');
  let source: string;
  try {
    source = (
      generate as (
        document: Readonly<Record<string, unknown>>,
        options: IClientGenerationOptions,
      ) => string
    )(document, options);
  } catch (cause) {
    const codegenError = sdk['OpenApiCodegenError'];
    if (
      typeof codegenError === 'function' &&
      cause instanceof codegenError &&
      cause instanceof Error &&
      cause.message.includes("'Api'")
    )
      throw new Error(`${cause.message}; choose another name with --type-name.`, { cause });
    throw cause;
  }
  const header =
    runtime === 'deno'
      ? '// deno-fmt-ignore-file\n// deno-lint-ignore-file'
      : '/* eslint-disable */';
  const file: GeneratedFile = {
    path,
    contents: `${CLIENT_MARKER}\n${header}\n${source}`,
    managed: true,
  };
  const files = await formatForTarget([file], runtime, root, report, () =>
    projectPrettier(root, load),
  );
  return files[0]!;
}
